using Microsoft.AspNetCore.Mvc; using System.Text.Json; using RaceDay.MvC.Models; using RaceDay.MvC.Services;
namespace RaceDay.MvC.Controllers;
public class EventsController(RaceDayApiClient api):Controller { public async Task<IActionResult> Index(string? q,string? type){var r=await api.Get<List<EventViewModel>>("api/events");ViewBag.Error=r.Error;var list=r.Data??new();if(!string.IsNullOrWhiteSpace(q))list=list.Where(e=>(e.EventName+" "+e.Location).Contains(q,StringComparison.OrdinalIgnoreCase)).ToList();if(!string.IsNullOrWhiteSpace(type))list=list.Where(e=>e.EventType==type).ToList();ViewBag.Query=q;ViewBag.Type=type;return View(list);} public async Task<IActionResult> Details(int id){var r=await api.Get<EventViewModel>($"api/events/{id}");if(!r.Ok||r.Data is null)return NotFound();var categories=await api.Get<List<EventCategoryViewModel>>($"api/categories/event/{id}");r.Data.Categories=categories.Data??new();ViewBag.Error=categories.Error;return View(r.Data);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Enrol(int id,int eventCategoryId,string? raceNumber){if(HttpContext.Session.GetInt32("UserID")==null)return RedirectToAction("Login","Account");if(HttpContext.Session.GetString("Role")!="Participant")return Forbid();var r=await api.Send<JsonElement>(HttpMethod.Post,"api/enrolments",new{EventCategoryID=eventCategoryId,RaceNumber=raceNumber});TempData[r.Ok?"Success":"Error"]=r.Error??(r.Ok?"You have joined the event.":"Could not join the event.");return RedirectToAction(nameof(Details),new{id});} }
